import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;

public class TimezoneHandler {
    // Always accept absolute points in time or parse with explicit zones
    public static void processUserEvent(String isoTimestamp, String userZoneId) {
        Instant instant = Instant.parse(isoTimestamp);
        ZoneId targetZone = ZoneId.of(userZoneId);

        ZonedDateTime userTime = instant.atZone(targetZone);
        System.out.println("User local time: " + userTime.format(DateTimeFormatter.ISO_ZONED_DATE_TIME));
    }
}
